std::vector<int> bfs_distances(int n, const std::vector<std::pair<int, int>>& edges, int source) {
    std::vector<int> dist(n, -1);
    if (n <= 0) return dist;
    if (source < 0 || source >= n) return dist;

    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e.first, v = e.second;
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::queue<int> q;
    dist[source] = 0;
    q.push(source);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist;
}
